package com.exelynt.booking.service;
import com.exelynt.booking.dto.*; import com.exelynt.booking.repository.UserRepository; import com.exelynt.booking.security.JwtService; import org.springframework.security.authentication.*; import org.springframework.stereotype.Service;
@Service public class AuthService { private final AuthenticationManager manager; private final JwtService jwt; private final UserRepository users; public AuthService(AuthenticationManager manager,JwtService jwt,UserRepository users){this.manager=manager;this.jwt=jwt;this.users=users;} public LoginResponse login(LoginRequest request){manager.authenticate(new UsernamePasswordAuthenticationToken(request.username(),request.password()));var user=users.findByUsername(request.username()).orElseThrow(()->new BadCredentialsException("Invalid credentials"));return new LoginResponse(jwt.generate(user),"Bearer",user.getUsername(),user.getRole().name());} }
